28	/// The multicodec of the DAG-root `contentCid`: `dag-cbor` (0x71). Engine-owned
29	/// (#630, engine.md:497) — core keeps the leaf `raw` codec but takes the root
30	/// codec as a parameter. Single-byte, inside core's frozen content-plane set.
31	pub const DAG_ROOT_CODEC: u8 = 0x71;
32	
33	/// CIDv1 version byte, and the digest-length byte (BLAKE3-256 = 32) — the two
