/// `Err`, so this crate never publishes a root its own `read_block` rejects
/// (#788 — the encode/decode fail-closed symmetry of AGENTS.md rule 8).
pub(crate) const MAX_RESOLVED_RECORD_BYTES: usize = 4 * 1024 * 1024;

